"use client";

import { createContext, useContext, useState, useCallback, useEffect, type ReactNode } from "react";

export type Locale = "en" | "ar";

interface I18nContextValue {
  locale: Locale;
  setLocale: (l: Locale) => void;
  t: (key: string, params?: Record<string, string>) => string;
  dir: "ltr" | "rtl";
}

const I18nContext = createContext<I18nContextValue | null>(null);

const STORAGE_KEY = "sx_locale";

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>("en");
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    const stored = (localStorage.getItem(STORAGE_KEY) as Locale) || "en";
    const frame = requestAnimationFrame(() => {
      setMounted(true);
      if (stored !== locale) setLocaleState(stored);
    });
    return () => cancelAnimationFrame(frame);
  }, [locale]);

  const setLocale = useCallback((l: Locale) => {
    setLocaleState(l);
    if (typeof window !== "undefined") {
      localStorage.setItem(STORAGE_KEY, l);
    }
  }, []);

  useEffect(() => {
    if (!mounted) return;
    document.documentElement.lang = locale;
    document.documentElement.dir = locale === "ar" ? "rtl" : "ltr";
  }, [locale, mounted]);

  const t = useCallback(
    (key: string, params?: Record<string, string>): string => {
      const dict = locale === "ar" ? arDict : enDict;
      let value = dict[key] || key;
      if (params) {
        for (const [k, v] of Object.entries(params)) {
          value = value.replace(new RegExp(`\\{${k}\\}`, "g"), v);
        }
      }
      return value;
    },
    [locale]
  );

  const dir = locale === "ar" ? "rtl" : "ltr";

  return (
    <I18nContext.Provider value={{ locale, setLocale, t, dir }}>
      {children}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  const ctx = useContext(I18nContext);
  if (!ctx) throw new Error("useI18n must be used within I18nProvider");
  return ctx;
}

/** Translate a role slug (admin/manager/accountant/staff/cashier) or fall back to the raw slug. */
export function roleLabel(t: (key: string) => string, role?: string | null): string {
  if (!role) return "";
  const key = `profile.role_${role}`;
  const translated = t(key);
  return translated.startsWith("profile.role_") ? role : translated;
}

const BUSINESS_TYPE_KEYS: Record<string, string> = {
  supermarket_hypermarket: "sector.supermarket",
  supermarket: "sector.supermarket",
  grocery: "sector.supermarket",
  clothing_apparel: "sector.clothing_apparel",
  electronics_warranty: "sector.electronics_warranty",
  fast_food_kds: "sector.fast_food_kds",
  fine_dining_reservations: "sector.fine_dining_reservations",
  dental_charting: "sector.dental_charting",
  general_clinic: "sector.general_clinic",
  jewelry_store: "sector.jewelry_store",
};

/** Translate a business-type slug (e.g. supermarket_hypermarket) into a human-readable locale-aware label or fall back to the raw slug. */
export function businessTypeLabel(t: (key: string) => string, slug?: string | null): string {
  if (!slug) return "—";
  const key = BUSINESS_TYPE_KEYS[slug];
  if (!key) return slug;
  const translated = t(key);
  return translated.startsWith("sector.") ? slug : translated;
}

