  "landing.features_subtitle": "\u0646\u0638\u0627\u0645 \u0648\u0627\u062D\u062F \u064A\u062A\u0643\u064A\u0641 \u0645\u0639 \u0639\u0645\u0644\u0643. \u0645\u0646\u0635\u0629 \u0648\u0627\u062D\u062F\u0629 \u062A\u062A\u0634\u0643\u0644 \u0644\u064A\u0646\u0627\u0633\u0628 \u0627\u0644\u062D\u0627\u062C\u0629 \u0627\u0644\u0635\u0646\u0627\u0639\u064A\u0629 \u0627\u0644\u062F\u0642\u064A\u0642\u064A\u0629.",
