  "landing.how_step1_desc": "\u0623\u0639\u0644\u0646 \u0627\u0644\u0646\u0638\u0627\u0645 \u0628\u0646\u0648\u0639 \u0639\u0645\u0644\u0643. \u064A\u062D\u0645\u0644\u200C \u0645\u062D\u0631\u0643 \u0627\u0644\u062A\u062D\u0648\u0644 \u0627\u0644\u0647\u064A\u0643\u0644 \u0648\u0627\u0644\u0648\u0627\u062C\u0647\u0629 \u0648\u0627\u0644\u062A\u0646\u0642\u0644 \u0627\u0644\u0645\u0646\u0627\u0633\u0628.",
