  "landing.how_step3": "\u0648\u0633\u0651\u0639 \u0628\u062F\u0648\u0646 \u062D\u062F\u0648\u062F",
  "landing.how_step3_desc": "\u0623\u0636\u0641 \u0641\u0631\u0648\u0639\u0627\u064B \u0648\u0645\u0646\u062A\u062C\u0627\u062A \u0648\u0645\u0633\u062A\u062E\u062F\u0645\u064A\u0646. \u0627\u0644\u0628\u0646\u064A\u0629 \u0645\u062A\u0639\u062F\u062F\u0629 \u0627\u0644\u0645\u0633\u062A\u0623\u062C\u0631\u064A\u0646 \u062A\u0646\u0645\u0648 \u0645\u0639\u0643 \u0645\u0646 \u0627\u0644\u064A\u0648\u0645 \u0627\u0644\u0623\u0648\u0644.",
  "landing.cta_title": "\u062C\u0627\u0647\u0632 \u0644\u0644\u062A\u062E\u0644\u0635 \u0645\u0646 \u0627\u0644\u0623\u0648\u0631\u0627\u0642\u061F",
  "landing.cta_desc": "\u0627\u0628\u062F\u0623 \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0645\u062C\u0627\u0646\u064A \u0627\u0644\u064A\u0648\u0645 \u0648\u0627\u0644\u062A\u0641\u0636\u0644 \u0643\u064A\u0641 \u064A\u062D\u0648\u0644 \u0627\u0644\u0646\u0638\u0627\u0645 \u0639\u0645\u0644\u064A\u0627\u062A \u0634\u0631\u0643\u062A\u0643 \u0641\u064A \u062F\u0642\u0627\u0626\u0642 \u0648\u0644\u064A\u0633 \u0634\u0647\u0648\u0631.",
  "landing.footer_tagline": "\u0646\u0638\u0627\u0645 ERP SaaS \u0645\u062A\u0639\u062F\u062F \u0627\u0644\u0645\u0633\u062A\u0623\u062C\u0631\u064A\u0646 \u00B7 \u0645\u0628\u0646\u064A \u0644\u0644\u0633\u0648\u0642 \u0627\u0644\u0639\u0631\u0628\u064A \u00B7 \u0627\u0644\u0623\u0631\u062F\u0646",
  "landing.footer_rights": "\u062C\u0645\u064A\u0639 \u0627\u0644\u062D\u0642\u0648\u0642 \u0645\u062D\u0641\u0648\u0638\u0629.",

  // ─── Features ──────────────────────────────────────
  "features.morphing_engine_title": "\u0645\u062D\u0631\u0643 \u0627\u0644\u062A\u062D\u0648\u0644",
  "features.morphing_engine_desc": "\u0646\u0638\u0627\u0645 \u0648\u0627\u062D\u062F \u064A\u062A\u0643\u064A\u0641 \u0648\u0627\u062C\u0647\u062A\u0647 \u0648\u0645\u0645\u064A\u0632\u0627\u062A\u0647 \u0648\u0633\u064A\u0631\u0629 \u0639\u0645\u0644\u0647 \u0644\u064A\u0646\u0627\u0633\u0628 \u0642\u0637\u0627\u0639\u0643 \u0627\u0644\u0635\u0646\u0627\u0639\u064A.",
