  "features.arabic_desc": "\u062F\u0639\u0645 \u0639\u0631\u0628\u064A \u0634\u0627\u0645\u0644 \u0645\u0639 \u062A\u0646\u0633\u064A\u0642 \u0645\u0646 \u0627\u0644\u064A\u0645\u064A\u0646 \u0625\u0644\u0649 \u0627\u0644\u064A\u0633\u0627\u0631 \u0648\u062A\u0646\u0633\u064A\u0642 \u0645\u062D\u0644\u064A.",
