  "features.analytics_desc": "\u0645\u0639\u0627\u0631\u0636 \u0648\u0644\u0648\u062D\u0627\u062A \u0648\u062A\u0642\u0627\u0631\u064A\u0631 \u062A\u062D\u062F\u062B \u0645\u0639 \u062A\u0633\u0631\u0639 \u0639\u0645\u0644\u0643.",
