  "features.verticals_desc": "\u0633\u0648\u0628\u0631\u0645\u0627\u0631\u0643\u062A\u060C \u0623\u0632\u064A\u0627\u0621\u060C \u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A\u0627\u062A\u060C \u0645\u0637\u0627\u0639\u0645\u060C \u0639\u064A\u0627\u062F\u0627\u062A\u060C \u0645\u062C\u0648\u0647\u0631\u0627\u062A \u0648\u0627\u0644\u0645\u0632\u064A\u062F.",
  "features.ai_title": "\u0628\u0646\u064A\u0629 \u0645\u062C\u0647\u0631\u0629 \u0644\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A",
